out={'schema':'marici.voevodsky.CR1-log-volume-can-var-bridge.v1','prospective_action':'CR1A1a1i1a1a2i1a1a2b1a1a_realize_log_volume_can_var_bridge','outcome_contract':{'++':'a D3-equivariant extraordinary-costalk can-var map realizes both top grades and all three pair restrictions','+-':'the absolute mixed block and complete finite endpoint-star matrix exist, but spatial extraordinary-costalk BC remains','-+':'the mixed block or endpoint-star orientations are incompatible','--':'the two-top source has no mixed block'},'resolution':'+-','mixed_block':{'identity':'dH_Sigma=q_Sigma-(x1 xi1+x3 xi3+x5 xi5)','absolute_d_squared':0,'D3_covariant':True,'Tor_grades':[0,1],'formal_endpoint_relative_top':'unique primitive','formal_absolute_top':'fails without endpoint-compatible map'},'endpoint_star':{'states_per_endpoint':27,'arrows_per_endpoint':54,'anchored_orientation_rebases':1,'radial_rows':54,'normal_rows':54,'state_Tor_rows':108,'arrow_Tor_rows':216,'integer_inverted':False},'remaining':'Construct one D3-equivariant marked extraordinary-costalk/Beck-Chevalley map compatible with the Yoneda cone roof and retaining all Tor1/excess copies.','refinement':['CR1A1a1i1a1a2i1a1a2b1a1a1_construct_D3_extraordinary_costalk_BC'],'next':'Build the costalk BC map; a fitted dc=qSigma column is prohibited.','checks':checks,'passed':True};p=ROOT/'research/voevodsky/results/CR1_log_volume_can_var_bridge.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'passed':True,'resolution':'+-','endpoint_states':54,'spatial_BC':False,'next':out['refinement'][0]}))
